// User storage and lookup.

const users = new Map<string, { id: string; name: string; role: 'user' | 'admin' }>();

export function findById(id: string) {
  return users.get(id) ?? null;
}

export function validateExists(id: string): boolean {
  return users.has(id);
}

export function create(user: { id: string; name: string; role: 'user' | 'admin' }) {
  if (users.has(user.id)) {
    throw new Error(`User ${user.id} already exists`);
  }
  users.set(user.id, user);
  return user;
}

export function clear() {
  users.clear();
}

// Permission checks.

import { findById } from './users.js';

export function canDelete(task: { createdBy: string }, userId: string): boolean {
  const actor = findById(userId);
  if (!actor) return false;
  if (actor.role === 'admin') return true;
  return task.createdBy === userId;
}

export function canExport(userId: string): boolean {
  const actor = findById(userId);
  if (!actor) return false;
  return actor.role === 'admin';
}

// In-memory cache with TTL.

type CacheEntry<T> = { value: T; expiresAt: number };

export class Cache {
  private store = new Map<string, CacheEntry<unknown>>();

  set<T>(key: string, value: T, ttlMs: number) {
    this.store.set(key, { value, expiresAt: Date.now() + ttlMs });
  }

  get<T>(key: string): T | null {
    const entry = this.store.get(key);
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return null;
    }
    return entry.value as T;
  }

  invalidate(key: string) {
    this.store.delete(key);
  }
}

// Audit log.

export type AuditEntry = {
  action: 'create' | 'status_change' | 'delete' | 'export';
  userId: string;
  taskId?: string;
  details?: string;
  timestamp: number;
};

const entries: AuditEntry[] = [];

export function record(entry: AuditEntry) {
  entries.push(entry);
}

export function list(): AuditEntry[] {
  return entries;
}

export function clear() {
  entries.length = 0;
}

// CSV exporter.

import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function escapeCsv(value: string): string {
  if (value.includes(',') || value.includes('"') || value.includes('\n')) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error(`User ${userId} does not have export permission`);
  }

  const tasks = taskManager.list();
  const header = 'id,title,status,assignee,createdAt';
  const rows = tasks.map((t) =>
    [t.id, t.title, t.status, t.assignee, String(t.createdAt)]
      .map(escapeCsv)
      .join(',')
  );
  const csv = [header, ...rows].join('\n');

  record({
    action: 'export',
    userId,
    details: `${tasks.length} tasks exported`,
    timestamp: Date.now(),
  });

  return csv;
}

