console.log('[INTEGRATION TEST] createUser:', typeof createUser, createUser);

const alice = { id: 'u1', name: 'Alice', role: 'user' as const };
const bob = { id: 'u2', name: 'Bob', role: 'user' as const };
const admin = { id: 'u3', name: 'Admin', role: 'admin' as const };

beforeEach(() => {
  clearUsers();
  taskManager.clear();
  clearAudit();
});

describe('feature-spec-001 integration', () => {
  it('creates task with valid user', () => {
    console.log('[TEST] about to call createUser');
    createUser(alice);
    console.log('[TEST] createUser succeeded');
    const task = taskManager.create({
      title: 'Fix bug',
      description: 'desc',
      status: 'open',
      createdBy: alice.id,
      assignee: alice.id,
    });
    expect(task.id).toBeDefined();
    expect(task.title).toBe('Fix bug');
  });

  it('rejects invalid assignee', () => {
    expect(() =>
      taskManager.create({
        title: 'Fix bug',
        description: 'desc',
        status: 'open',
        createdBy: 'u99',
        assignee: 'u99',
      }),
    ).toThrow();
  });

  it('rejects empty title', () => {
    createUser(alice);
    expect(() =>
      taskManager.create({
        title: '',
        description: 'desc',
        status: 'open',
        createdBy: alice.id,
        assignee: alice.id,
      }),
    ).toThrow();
  });

  it('enforces status transition open -> in_progress -> done', () => {
    createUser(alice);
    const task = taskManager.create({
      title: 'Task',
      description: 'desc',
      status: 'open',
      createdBy: alice.id,
      assignee: alice.id,
    });
    taskManager.updateStatus(task.id, 'in_progress');
    taskManager.updateStatus(task.id, 'done');
    expect(() => taskManager.updateStatus(task.id, 'done')).toThrow();
  });

  it('allows admin to delete any task', () => {
    createUser(alice);
    createUser(admin);
    const task = taskManager.create({
      title: 'Task',
      description: 'desc',
      status: 'open',
      createdBy: alice.id,
      assignee: alice.id,
    });
    expect(taskManager.delete(task.id, admin.id)).toBe(true);
  });

  it('denies non-owner non-admin delete', () => {
    createUser(alice);
    createUser(bob);
    const task = taskManager.create({
      title: 'Task',
      description: 'desc',
      status: 'open',
      createdBy: alice.id,
      assignee: alice.id,
    });
    expect(taskManager.delete(task.id, bob.id)).toBe(false);
  });

  it('cache miss returns null', () => {
    const cache = new Cache();
    expect(cache.get('missing')).toBeNull();
  });

  it('invalidates cache on status change', () => {
    createUser(alice);
    const task = taskManager.create({
      title: 'Task',
      description: 'desc',
      status: 'open',
      createdBy: alice.id,
      assignee: alice.id,
    });
    const cache = new Cache();
    cache.set(task.id, task, 60000);
    taskManager.updateStatus(task.id, 'in_progress');
    expect(cache.get(task.id)).toBeNull();
  });

  it('records audit on create', () => {
    createUser(alice);
    taskManager.create({
      title: 'Task',
      description: 'desc',
      status: 'open',
      createdBy: alice.id,
      assignee: alice.id,
    });
    const entries = list();
    expect(entries.filter((e) => e.action === 'create')).toHaveLength(1);
  });

  it('records audit on status change', () => {
    createUser(alice);
    const task = taskManager.create({
      title: 'Task',
      description: 'desc',
      status: 'open',
      createdBy: alice.id,
      assignee: alice.id,
    });
    taskManager.updateStatus(task.id, 'in_progress');
    const entries = list();
    expect(entries.filter((e) => e.action === 'status_change')).toHaveLength(1);
  });

  it('export requires permission', () => {
    createUser(alice);
    createUser(bob);
    const task = taskManager.create({
      title: 'Task',
      description: 'desc',
      status: 'open',
      createdBy: alice.id,
      assignee: alice.id,
    });
    expect(() => exportTasks(bob.id)).toThrow();
  });

