{"content": "// Task CRUD and status transitions.

import { findById, validateExists } from './users.ts';
import { canDelete } from './permissions.ts';
import { Cache } from './cache.ts';
import { record } from './audit.ts';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

// Valid status transition: key -> next only
const STATUS_FLOW: Record<Task['status'], Task['status'] | null> = {
  open: 'in_progress',
  in_progress: 'done',
  done: null,
};

type InvalidateListener = (key: string) => void;

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache = new Cache();
  private invalidateListeners: InvalidateListener[] = [];

  registerInvalidateListener(fn: InvalidateListener) {
    this.invalidateListeners.push(fn);
  }

  private invalidateCache(key: string) {
    this.cache.invalidate(key);
    for (const fn of this.invalidateListeners) {
      fn(key);
    }
  }

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (!input.title || input.title.trim() === '') {
      throw new Error('Title must not be empty');
    }
    if (!validateExists(input.createdBy)) {
      throw new Error(`User ${input.createdBy} does not exist`);
    }
    if (!validateExists(input.assignee)) {
      throw new Error(`User ${input.assignee} does not exist`);
    }

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };
    this.tasks.set(task.id, task);

    record({
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      timestamp: Date.now(),
    });

    return task;
  }

  getTask(id: string): Task | null {
    const cached = this.cache.get<Task | null>(id);
    if (cached !== null) return cached;

    const task = this.tasks.get(id) ?? null;
    if (task) {
      this.cache.set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const next = STATUS_FLOW[task.status];
    if (next === null || next !== status) {
      throw new Error(
        `Invalid status transition: ${task.status} -> ${status}`
      );
    }

    task.status = status;
    this.invalidateCache(id);

    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: id,
      details: status,
      timestamp: Date.now(),
    });

    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;

    if (!canDelete(task, userId)) return false;

    this.tasks.delete(id);
    this.invalidateCache(id);

    record({
      action: 'delete',
      userId,
      taskId: id,
      timestamp: Date.now(),
    });

    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId
    );
  }

  list(): Task[] {
    return Array.from(this.tasks.values());
  }

  clear() {
    this.tasks.clear();
    this.cache = new Cache();
    this.invalidateListeners = [];
  }
}

export const taskManager = new TaskManager();
", "path": "src/tasks.ts"}

